from pathlib import Path
import re

root=Path('public')
index=(root/'index.html').read_text()
app=(root/'assets/app-base.js').read_text()
calc_html=(root/'preisrechner/index.html').read_text()
calc_js=(root/'assets/calculator.js').read_text()
styles=(root/'assets/styles.css').read_text()
calc_css=(root/'assets/calculator.css').read_text()

# Main navigation + same-tab calculator + remove service icons.
index=index.replace('<a href="#leistungen">Leistungen</a>\n<a href="#warum">Warum FrankiFlow</a>', '<a href="#leistungen">Leistungen</a>\n<a href="#about">Über uns</a>\n<a href="https://accommodation.frankiflow.de/">FrankiFlow Accommodations</a>\n<a href="#warum">Warum FrankiFlow</a>',1)
index=re.sub(r'(<a[^>]+href="/preisrechner/"[^>]*)\s+rel="noopener"\s+target="_blank"',r'\1',index)
index=re.sub(r'<span class="service-icon">.*?</span>', '', index, flags=re.S)

about='''\n<section class="section about-main-section" id="about">\n<div class="container">\n<div class="section-head modern-head"><div><span class="eyebrow">Über uns</span><h2>Die Geschichte hinter <span class="teal-text">FrankiFlow.</span></h2></div><p>Persönlicher Service, Technologie und nachhaltiges Wachstum aus Frankfurt.</p></div>\n<div class="about-accordion" id="aboutAccordion"><div class="about-loading">Inhalt wird geladen …</div></div>\n</div>\n</section>\n'''
marker='<section class="section process-section" id="ablauf">'
if 'id="about"' not in index:
    index=index.replace(marker,about+marker,1)
index=index.replace('<a href="#warum">Warum FrankiFlow</a><a href="#ablauf">So funktioniert’s</a>', '<a href="#about">Über uns</a><a href="#warum">Warum FrankiFlow</a><a href="#ablauf">So funktioniert’s</a>',1)
index=index.replace('<a href="/datenschutz/">Datenschutz</a>', '<a href="/datenschutz/">Datenschutz</a><a href="/company-policy/">Company Policy</a>',1)

# Main page About loader and admin enquiry mail flow.
old_submit="""  const {error}=await supabase.from('frankiflow_quote_requests').insert(payload);btn.disabled=false;btn.innerHTML=old;translateDom(btn,getLanguage());\n  if(error){notice.innerHTML=tr(`Die Online-Anfrage konnte nicht gesendet werden. Schreiben Sie uns bitte direkt an <a href=\"mailto:${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}\">${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}</a>.`,`The online enquiry could not be sent. Please email us directly at <a href=\"mailto:${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}\">${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}</a>.`);notice.className='notice error';return}\n  form.reset();notice.textContent=tr('Vielen Dank! Ihre Anfrage ist eingegangen. Wir melden uns persönlich bei Ihnen.','Thank you! We received your enquiry and will contact you personally.');notice.className='notice';"""
new_submit="""  const {data:created,error}=await supabase.from('frankiflow_quote_requests').insert(payload).select('id').single();btn.disabled=false;btn.innerHTML=old;translateDom(btn,getLanguage());\n  if(error){notice.innerHTML=tr(`Die Online-Anfrage konnte nicht gesendet werden. Schreiben Sie uns bitte direkt an <a href=\"mailto:${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}\">${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}</a>.`,`The online enquiry could not be sent. Please email us directly at <a href=\"mailto:${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}\">${siteSettings?.email||FRANKIFLOW_CONFIG.defaultEmail}</a>.`);notice.className='notice error';return}\n  const emailBody={quote_request_id:created.id,customer_email:String(payload.customer_email||'').trim().toLowerCase(),language:getLanguage()};\n  await Promise.allSettled([\n    supabase.functions.invoke('frankiflow-email',{body:{event_type:'admin_enquiry',...emailBody,attach_quote:false,quote_snapshot:{service_label:form.querySelector('[name=service_key] option:checked')?.textContent||payload.service_key}}}),\n    supabase.functions.invoke('frankiflow-email',{body:{event_type:'enquiry_received',...emailBody}})\n  ]);\n  form.reset();notice.textContent=tr('Vielen Dank! Ihre Anfrage ist eingegangen. Wir melden uns persönlich bei Ihnen.','Thank you! We received your enquiry and will contact you personally.');notice.className='notice';"""
if old_submit not in app: raise SystemExit('submitQuote snippet changed')
app=app.replace(old_submit,new_submit,1)
about_loader="""\nasync function loadAboutMain(){\n  const host=$('#aboutAccordion');if(!host)return;\n  const {data}=await supabase.from('frankiflow_site_settings').select('about_sections').eq('id',1).maybeSingle();\n  const sections=Array.isArray(data?.about_sections)?data.about_sections:[];const lang=getLanguage();\n  host.innerHTML=sections.slice(0,3).map(item=>{const heading=lang==='en'?(item.heading_en||item.heading_de):(item.heading_de||item.heading_en);const body=lang==='en'?(item.body_en||item.body_de):(item.body_de||item.body_en);const paragraphs=String(body||'').split(/\\n\\s*\\n/).map(x=>x.trim()).filter(Boolean);return `<details class=\"about-accordion-item\"><summary>${escapeHtml(heading||'')}</summary><div class=\"about-accordion-copy\">${paragraphs.map(p=>`<p>${escapeHtml(p)}</p>`).join('')}</div></details>`}).join('');\n}\n"""
if 'async function loadAboutMain()' not in app:
    app=app.replace('async function loadGallery(){',about_loader+'\nasync function loadGallery(){',1)
app=app.replace("window.addEventListener('frankiflow:language',applySiteLanguage);", "window.addEventListener('frankiflow:language',()=>{applySiteLanguage();loadAboutMain()});",1)
app=app.replace('await Promise.allSettled([loadSite(),loadGallery(),loadHeaderLogoWidth()]);', 'await Promise.allSettled([loadSite(),loadGallery(),loadAboutMain(),loadHeaderLogoWidth()]);',1)

# About legacy page redirects to the new accordion section while preserving old links.
about_page=root/'about/index.html'
about_page.write_text('''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=/#about"><link rel="canonical" href="https://frankiflow.de/#about"><title>Über uns | FrankiFlow</title></head><body><p><a href="/#about">Über uns auf der Startseite öffnen</a></p><script>location.replace('/#about')</script></body></html>''')

# Company/service policy page.
policy=root/'company-policy/index.html';policy.parent.mkdir(parents=True,exist_ok=True)
policy.write_text('''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Company Policy | FrankiFlow</title><meta name="description" content="Service- und Unternehmensrichtlinien von FrankiFlow für Reinigung und Objektbetreuung."><link rel="icon" href="/assets/frankiflow-logo.png"><link rel="stylesheet" href="/assets/styles.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="/"><img src="/assets/frankiflow-logo.png" alt="FrankiFlow"></a><nav class="nav-links"><a href="/">Startseite</a><a href="/#leistungen">Leistungen</a><a href="/#kontakt">Kontakt</a></nav></div></header><main class="section policy-page"><div class="container policy-wrap"><span class="eyebrow">FrankiFlow</span><h1>Company Policy</h1><p class="lead-small">Diese Richtlinie ergänzt unsere Datenschutzinformationen und beschreibt die praktischen Regeln für unsere Reinigungs- und Objektbetreuungsleistungen.</p><section><h2>Angebote & Leistungsumfang</h2><p>Online berechnete Preise sind unverbindliche Richtwerte. Verbindlich wird ein Auftrag erst nach Bestätigung des konkreten Leistungsumfangs, der Häufigkeit, der Objektbedingungen und gegebenenfalls einer Besichtigung.</p></section><section><h2>Zugang & Mitwirkung</h2><p>Kundinnen und Kunden stellen sicher, dass vereinbarte Zugänge, Schlüssel, Codes sowie notwendige Informationen rechtzeitig verfügbar sind. Besondere Oberflächen, Sicherheitsanforderungen oder empfindliche Gegenstände sind vor Beginn mitzuteilen.</p></section><section><h2>Zahlung</h2><p>Preise, Zahlungsart und Fälligkeit werden im Angebot oder Vertrag festgelegt. Zusatzleistungen, die nachträglich beauftragt werden, können separat berechnet werden.</p></section><section><h2>Terminänderung & Stornierung</h2><p>Änderungen sollten so früh wie möglich mitgeteilt werden. Kurzfristige Stornierungen oder nicht zugängliche Objekte können entsprechend der individuellen Vereinbarung berechnet werden.</p></section><section><h2>Schlüssel & Eigentum</h2><p>Überlassene Schlüssel und Zugangsdaten werden ausschließlich für den vereinbarten Auftrag verwendet und sorgfältig behandelt. Ein Verlust oder Schaden wird unverzüglich gemeldet und nach den vereinbarten Haftungsbedingungen bearbeitet.</p></section><section><h2>Schäden & Haftung</h2><p>Festgestellte Schäden sind möglichst zeitnah zu melden. FrankiFlow prüft den Vorgang und wickelt berechtigte Fälle im Rahmen der vertraglichen Vereinbarung und bestehenden Betriebshaftpflicht ab.</p></section><section><h2>Qualität & Beschwerden</h2><p>Beanstandungen sollen zeitnah und mit möglichst konkreten Angaben oder Fotos gemeldet werden. Unser Ziel ist eine schnelle, faire Nachbesserung und eine klare Abstimmung für zukünftige Einsätze.</p></section><section><h2>Datenschutz</h2><p>Personenbezogene Daten werden ausschließlich für Anfrage, Vertragsabwicklung und Kommunikation verarbeitet. Einzelheiten finden Sie in unserer <a href="/datenschutz/">Datenschutzerklärung</a>.</p></section><p class="muted">Stand: September 2026 · FrankiFlow Gebäudereinigung & Objektbetreuung · Inhaber: Inura Devasurendra</p></div></main></body></html>''')

# Calculator direct request button/modal + persistent price island.
calc_html=calc_html.replace('<a class="btn-calc ghost" data-i18n="request" href="/#kontakt">Persönliches Angebot anfragen</a>', '<button class="btn-calc ghost" id="requestService" type="button">Service direkt anfragen</button>',1)
modal='''\n<div class="quote-request-modal hidden" id="quoteRequestModal" aria-hidden="true"><div class="quote-request-dialog"><div class="quote-request-head"><div><span>FrankiFlow</span><h2 id="requestDialogTitle">Service direkt anfragen</h2></div><button type="button" id="closeRequestDialog" aria-label="Close">×</button></div><div class="quote-request-summary" id="requestQuoteSummary"></div><div class="field"><label id="requestMessageLabel">Nachricht</label><textarea id="requestMessage" rows="5" placeholder="Ergänzen Sie besondere Wünsche, Terminvorstellungen oder Zugangsinformationen."></textarea></div><label class="request-policy"><input id="requestPrivacy" type="checkbox"> <span>Ich stimme der Verarbeitung meiner Angaben gemäß <a href="/datenschutz/">Datenschutz</a> zu.</span></label><div class="notice hidden" id="requestNotice"></div><div class="quote-request-actions"><button class="btn-calc ghost" type="button" id="cancelRequestDialog">Abbrechen</button><button class="btn-calc primary" type="button" id="submitServiceRequest">Anfrage mit Angebot senden</button></div></div></div>\n<div class="price-island" id="priceIsland" aria-live="polite"><div><span id="islandVisitLabel">Pro Termin</span><strong id="islandVisit">€0.00</strong></div><div><span id="islandMonthLabel">Pro Monat</span><strong id="islandMonth">€0.00</strong></div><div class="price-island-feature"><span id="islandFirstLabel">1. Monat</span><strong id="islandFirst">€0.00</strong></div></div>\n'''
if 'id="quoteRequestModal"' not in calc_html:
    calc_html=calc_html.replace('<div class="print-sheet" id="printSheet"',modal+'<div class="print-sheet" id="printSheet"',1)

# Print identity wording/logo and island update.
calc_js=calc_js.replace('<div class="print-footer-title">FrankiFlow Unternehmensdaten</div>', '<div class="print-footer-title">FrankiFlow Gebäudereinigung &amp; Objektbetreuung · Gründer: Inura Devasurendra</div>',1)
calc_js=calc_js.replace("  updateServiceMode();\n  renderChecklistPreview();", "  updateServiceMode();\n  const iv=$('#islandVisit'),im=$('#islandMonth'),ifm=$('#islandFirst');if(iv)iv.textContent=money(calc.visitTotal);if(im)im.textContent=money(calc.monthly);if(ifm)ifm.textContent=money(calc.firstMonth);\n  renderChecklistPreview();",1)
request_js=r'''\nfunction quoteSnapshot(){return{service_label:calc?.serviceLabel||'',frequency_label:calc?.freq?.label||$('#frequency option:checked')?.textContent||'',visit_price:calc?money(calc.visitTotal):'',monthly_price:calc?money(calc.monthly):'',first_month_price:calc?money(calc.firstMonth):'',breakdown:$('#breakdownRows')?.innerText||'',address:$('#customerAddress')?.value?.trim()||''};}\nfunction openServiceRequest(){if(!calc)return;const name=$('#customerName').value.trim(),email=$('#customerEmail').value.trim();if(!name||!email){alert(currentLang==='de'?'Bitte zuerst Name und E-Mail unter Kundendaten eintragen.':'Please enter your name and email in Customer details first.');return}const modal=$('#quoteRequestModal');$('#requestQuoteSummary').innerHTML=`<strong>${escapeHtml(calc.serviceLabel)}</strong><span>${money(calc.visitTotal)} / ${currentLang==='de'?'Termin':'visit'}</span><span>${money(calc.monthly)} / ${currentLang==='de'?'Monat':'month'}</span><b>${currentLang==='de'?'1. Monat':'1st month'}: ${money(calc.firstMonth)}</b>`;$('#requestPrivacy').checked=false;$('#requestNotice').className='notice hidden';modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');}\nfunction closeServiceRequest(){const m=$('#quoteRequestModal');m?.classList.add('hidden');m?.setAttribute('aria-hidden','true');}\nasync function submitServiceRequest(){if(!calc)return;const notice=$('#requestNotice');if(!$('#requestPrivacy').checked){notice.textContent=currentLang==='de'?'Bitte stimmen Sie der Datenschutzerklärung zu.':'Please accept the privacy policy.';notice.className='notice error';return}const btn=$('#submitServiceRequest'),old=btn.textContent;btn.disabled=true;btn.textContent=currentLang==='de'?'Wird gesendet …':'Sending …';const payload={service_key:calc.serviceKey,frequency_key:calc.freq?.key||$('#frequency').value,area_sqm:calc.area||null,contract_months:calc.months||null,window_sqm:calc.windowArea||0,equipment_by_frankiflow:!!calc.equipment,deep_cleaning:!!calc.deep,estimated_monthly:Number(calc.monthly.toFixed(2)),customer_name:$('#customerName').value.trim(),customer_email:$('#customerEmail').value.trim().toLowerCase(),customer_phone:$('#customerPhone').value.trim(),postcode:'',company_name:$('#customerCompany').value.trim(),message:$('#requestMessage').value.trim(),privacy_accepted:true,status:'new'};const {data,error}=await supabase.from('frankiflow_quote_requests').insert(payload).select('id').single();if(error){notice.textContent=error.message;notice.className='notice error';btn.disabled=false;btn.textContent=old;return}const common={quote_request_id:data.id,customer_email:payload.customer_email,language:currentLang};const results=await Promise.allSettled([supabase.functions.invoke('frankiflow-email',{body:{event_type:'admin_enquiry',...common,attach_quote:true,quote_snapshot:quoteSnapshot()}}),supabase.functions.invoke('frankiflow-email',{body:{event_type:'enquiry_received',...common}})]);const admin=results[0];if(admin.status==='rejected'||admin.value?.error){notice.textContent=currentLang==='de'?'Die Anfrage wurde gespeichert, aber die E-Mail konnte nicht versendet werden. Bitte kontaktieren Sie uns direkt.':'Your request was saved, but the email could not be sent. Please contact us directly.';notice.className='notice error'}else{notice.textContent=currentLang==='de'?'Vielen Dank. Ihre Anfrage und das berechnete Angebot wurden an FrankiFlow gesendet.':'Thank you. Your request and calculated quotation were sent to FrankiFlow.';notice.className='notice';setTimeout(closeServiceRequest,1400)}btn.disabled=false;btn.textContent=old;}\n'''
if 'function quoteSnapshot()' not in calc_js:
    calc_js=calc_js.replace("$$('[data-lang]').forEach",request_js+"\n$$('[data-lang]').forEach",1)
calc_js=calc_js.replace("$('#calculatorForm').addEventListener('input',calculate);", "$('#requestService')?.addEventListener('click',openServiceRequest);$('#closeRequestDialog')?.addEventListener('click',closeServiceRequest);$('#cancelRequestDialog')?.addEventListener('click',closeServiceRequest);$('#submitServiceRequest')?.addEventListener('click',submitServiceRequest);$('#calculatorForm').addEventListener('input',calculate);",1)

# CSS additions.
styles += '''\n\n/* September 2026: About accordion + policy */\n.about-accordion{display:grid;gap:12px}.about-accordion-item{border:1px solid var(--line,#dce8e5);border-radius:16px;background:#fff;overflow:hidden}.about-accordion-item summary{cursor:pointer;list-style:none;padding:18px 20px;font-weight:800;color:#0b3447;display:flex;justify-content:space-between;align-items:center}.about-accordion-item summary::-webkit-details-marker{display:none}.about-accordion-item summary:after{content:'+';font-size:22px;color:#218b91}.about-accordion-item[open] summary:after{content:'−'}.about-accordion-copy{padding:0 20px 18px}.about-accordion-copy p{text-align:justify;line-height:1.72;margin:0 0 13px}.policy-page{padding-top:130px}.policy-wrap{max-width:880px}.policy-wrap section{padding:18px 0;border-bottom:1px solid #dce8e5}.policy-wrap h1{font-size:clamp(36px,6vw,64px);color:#0b3447}.policy-wrap h2{font-size:20px}.policy-wrap p{line-height:1.72;text-align:justify}\n'''
calc_css += '''\n\n/* Direct service request + persistent live-price island */\n.price-island{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:70;display:flex;align-items:stretch;gap:1px;padding:5px;background:rgba(8,36,51,.94);backdrop-filter:blur(16px);border:1px solid rgba(255,255,255,.15);border-radius:18px;box-shadow:0 18px 60px rgba(0,0,0,.24);color:#fff;min-width:min(560px,calc(100vw - 28px))}.price-island>div{flex:1;padding:8px 13px;display:flex;flex-direction:column;gap:2px}.price-island span{font-size:10px;opacity:.72}.price-island strong{font-size:15px}.price-island-feature{background:#1b9a91;border-radius:12px}.quote-request-modal{position:fixed;inset:0;z-index:110;background:rgba(4,20,28,.58);backdrop-filter:blur(8px);display:grid;place-items:center;padding:18px}.quote-request-modal.hidden{display:none}.quote-request-dialog{width:min(620px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:22px;padding:20px;box-shadow:0 35px 100px rgba(0,0,0,.3)}.quote-request-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.quote-request-head h2{margin:2px 0 12px}.quote-request-head>button{border:0;background:#edf4f3;border-radius:10px;width:38px;height:38px;font-size:24px}.quote-request-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;background:#f2f8f7;border-radius:14px;padding:14px;margin:8px 0 16px}.quote-request-summary>*{display:block}.quote-request-summary b{color:#147a75}.request-policy{display:flex;gap:8px;align-items:flex-start;font-size:12px;margin:12px 0}.quote-request-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}@media(max-width:680px){.price-island{bottom:10px;min-width:calc(100vw - 18px);border-radius:15px}.price-island>div{padding:7px 9px}.price-island strong{font-size:13px}.quote-request-summary{grid-template-columns:1fr}.quote-request-actions{display:grid;grid-template-columns:1fr}.quote-request-actions button{width:100%}}@media print{.price-island,.quote-request-modal{display:none!important}}\n'''

(root/'index.html').write_text(index)
(root/'assets/app-base.js').write_text(app)
(root/'preisrechner/index.html').write_text(calc_html)
(root/'assets/calculator.js').write_text(calc_js)
(root/'assets/styles.css').write_text(styles)
(root/'assets/calculator.css').write_text(calc_css)
